    """Split an expression into number, operator and parenthesis tokens."""
    tokens: list[str] = []
    i = 0
    length = len(expr)
    while i < length:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i
            while j < length and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif ch in "+-*/()":
            tokens.append(ch)
            i += 1
        else:
            raise _InvalidExpression
    return tokens


class _Parser:
    """Recursive-descent parser and evaluator for arithmetic expressions."""

    def __init__(self, tokens: list[str]) -> None:
        self._tokens = tokens
        self._pos = 0
        self.division_by_zero = False

    def _peek(self) -> str | None:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self) -> None:
        self._pos += 1

    def parse(self) -> Fraction:
        value = self._expr()
        if self._pos != len(self._tokens):
            raise _InvalidExpression
        return value

    def _expr(self) -> Fraction:
        value = self._term()
        while True:
            token = self._peek()
            if token == "+":
                self._advance()
                value += self._term()
            elif token == "-":
                self._advance()
                value -= self._term()
            else:
                return value

    def _term(self) -> Fraction:
        value = self._factor()
        while True:
            token = self._peek()
            if token == "*":
                self._advance()
                value *= self._factor()
            elif token == "/":
                self._advance()
                divisor = self._factor()
                if divisor == 0:
                    self.division_by_zero = True
                    value = Fraction(0)
                else:
                    value /= divisor
            else:
                return value

    def _factor(self) -> Fraction:
        token = self._peek()
        if token == "-":
            self._advance()
            return -self._factor()
        if token == "(":
            self._advance()
            value = self._expr()
